NOTES.ge3=`## जिल्हे कसे वाढले (26 ते 36)
1960 मध्ये 26 जिल्हे व 4 विभाग (मुंबई, पुणे, औरंगाबाद, नागपूर) होते. नंतर नाशिक व अमरावती विभाग बनून आज 6 विभाग आहेत.
|नवा जिल्हा|तारीख|मूळ जिल्हा|
|सिंधुदुर्ग|1 मे 1981|रत्नागिरी|
|जालना|1 मे 1981|औरंगाबाद|
|लातूर|16 ऑगस्ट 1982|उस्मानाबाद|
|गडचिरोली|26 ऑगस्ट 1982|चंद्रपूर|
|मुंबई उपनगर|1 ऑक्टोबर 1990|मुंबई|
|वाशिम|1 जुलै 1998|अकोला|
|नंदुरबार|1 जुलै 1998|धुळे|
|हिंगोली|1 मे 1999|परभणी|
|गोंदिया|1 मे 1999|भंडारा|
|पालघर|1 ऑगस्ट 2014|ठाणे|
## क्षेत्रफळ: मोठे व लहान जिल्हे (सुमारे, चौ.किमी)
- सर्वात मोठे: अहिल्यानगर (सुमारे 17,000) → पुणे (15,600) → नाशिक (15,500) → सोलापूर (14,900) → गडचिरोली (14,400).
- सर्वात लहान: मुंबई शहर (सुमारे 157) → मुंबई उपनगर (सुमारे 446).
- छत्रपती संभाजीनगर विभागात क्षेत्रफळाने सर्वात मोठा जिल्हा बीड आणि सर्वात लहान हिंगोली.
- अहिल्यानगर जिल्ह्याला सर्वाधिक 7 जिल्ह्यांच्या सीमा: नाशिक, छ. संभाजीनगर, बीड, धाराशिव, सोलापूर, पुणे, ठाणे.
- पुणे जिल्ह्याला 5 जिल्ह्यांच्या सीमा: ठाणे, रायगड, सातारा, सोलापूर, अहिल्यानगर. पुणे विभागातील सर्वात उत्तरेकडील तालुका जुन्नर.
- एकूण भौगोलिक क्षेत्र 307.70 लाख हेक्टर (= 3,07,713 चौ.किमी). महाराष्ट्राचा रेखांश विस्तार अक्षांश विस्तारापेक्षा जास्त आहे (पूर्व–पश्चिम लांबी जास्त). महाराष्ट्र पठाराची पूर्व–पश्चिम लांबी सुमारे 750 किमी.
- MPSC च्या एका उत्तरतालिकेत अक्षांश विस्तार 15°44′ उ. ते 22°6′ उ. असा दिला आहे; पुस्तकांनुसार मिनिटांचे आकडे बदलतात.
- मुंबईवरून सुमारे 18°55′ उत्तर अक्षवृत्त जाते.
## टोकाचे जिल्हे
उत्तरेकडील टोक: नंदुरबार · दक्षिणेकडील: सिंधुदुर्ग · पूर्वेकडील: गडचिरोली/गोंदिया · पश्चिमेकडील: पालघर–मुंबईचा किनारा. किनारपट्टी असलेले 7 जिल्हे: पालघर, ठाणे, मुंबई शहर, मुंबई उपनगर, रायगड, रत्नागिरी, सिंधुदुर्ग.
## बृहन्मुंबई
- मुंबई 7 बेटांवर वसली: कुलाबा, ओल्ड वुमन्स आयलंड (लहान कुलाबा), मुंबई बेट, माझगाव, परळ, वरळी, माहीम. ही बेटे भराव टाकून जोडली गेली (हॉर्नबी वेल्लार्ड).
- तुळशी, विहार व पवई तलाव मुंबई उपनगरात (संजय गांधी राष्ट्रीय उद्यान परिसर). मुंबईला पाणीपुरवठा: तानसा, वैतरणा (मोडकसागर), अप्पर व मिडल वैतरणा, भातसा, विहार, तुळशी.
- 1534 मध्ये पोर्तुगीजांकडे; 1661 मध्ये पोर्तुगीज राजकन्या कॅथरीनच्या लग्नात इंग्लंडचा राजा चार्ल्स दुसरा याला हुंडा; 1668 मध्ये ईस्ट इंडिया कंपनीला भाडेपट्ट्याने.
## ठिकाणांची टोपणनावे (जोड्या)
|ठिकाण|ओळख|
|भंडारा|तलावांचा जिल्हा|
|तोरणमाळ (नंदुरबार)|यशवंत तलाव; थंड हवेचे ठिकाण (धुळे नव्हे)|
|उदयपूर (राजस्थान)|सरोवरांचे शहर (City of lakes)|
|नागपूर|संत्र्यांचे शहर, भारताचा 'शून्य मैल' दगड|
|नाशिक|द्राक्षांची राजधानी (Wine capital)|
|कोल्हापूर|गुळाचे व कुस्तीचे शहर|
|सोलापूर|चादरींचे शहर|
|छ. संभाजीनगर|दरवाजांचे शहर (52 दरवाजे); पर्यटन राजधानी|
|पुणे|पूर्वेकडील ऑक्सफर्ड; विद्येचे माहेरघर|
|चंद्रपूर|काळ्या सोन्याचा (कोळसा) जिल्हा|
|जळगाव|केळीचे आगार|
|इचलकरंजी|महाराष्ट्राचे मँचेस्टर|`;

NOTES.ge4=`## सह्याद्री: आकडे व रचना
- महाराष्ट्रात सह्याद्रीची लांबी सुमारे 440 किमी; सरासरी उंची 900–1,200 मी. सह्याद्री हा महाराष्ट्राचा मुख्य जलविभाजक आहे: पश्चिमेकडे लहान, वेगवान कोकणी नद्या आणि पूर्वेकडे लांब पूर्ववाहिनी नद्या.
- सह्याद्रीचा पश्चिम उतार तीव्र (कडे), तर पूर्व उतार मंद आहे. पूर्वेकडील उताराला लागून असलेल्या डोंगराळ पट्ट्याला 'मावळ' म्हणतात; मावळ भाग पर्जन्यछायेत येत नाही (पाऊस भरपूर). त्यापलीकडे 'देश' हा पठारी भाग पर्जन्यछायेत येतो.
## उंच शिखरे (सुमारे मीटर; पुस्तकांनुसार आकडे थोडे बदलतात)
|शिखर|उंची|जिल्हा|
|कळसूबाई|1,646|अहिल्यानगर (अकोले); सर्वोच्च|
|साल्हेर|1,567|नाशिक (बागलाण); दुसरे|
|महाबळेश्वर|1,438|सातारा|
|हरिश्चंद्रगड (तारामती)|1,424|अहिल्यानगर|
|सप्तशृंगी|1,416|नाशिक (वणी)|
|तोरणा|1,404|पुणे|
|राजगड|1,376|पुणे|
|त्र्यंबकेश्वर (ब्रह्मगिरी)|1,304|नाशिक|
|बैराट|1,177|अमरावती (गाविलगड टेकड्या; विदर्भातील सर्वोच्च)|
उतरता क्रम लक्षात ठेवा: कळसूबाई > साल्हेर > महाबळेश्वर > हरिश्चंद्रगड > सप्तशृंगी > तोरणा > त्र्यंबकेश्वर. सातपुड्यातील अस्तंभा शिखर नंदुरबार जिल्ह्यात आहे; तोरणमाळही सातपुड्यातच आहे.
## सह्याद्रीच्या उपरांगा (उत्तरेकडून दक्षिणेकडे)
|रांग|कोणत्या खोऱ्यांना वेगळे करते|
|सातपुडा (व गाविलगड टेकड्या)|नर्मदा व तापी; महाराष्ट्राची उत्तर सीमा|
|सातमाळा–अजिंठा|तापी व गोदावरी|
|हरिश्चंद्र–बालाघाट|गोदावरी व भीमा|
|शंभू महादेव|भीमा व कृष्णा|
- गोदावरी खोऱ्याच्या उत्तरेस सातमाळा–अजिंठा आणि दक्षिणेस हरिश्चंद्र–बालाघाट डोंगर आहेत.
- पूर्व महाराष्ट्रातील टेकड्या: दरेकसा टेकड्या (गोंदिया), चिरोली टेकड्या (गडचिरोली), भामरागड व सुरजागड (गडचिरोली), गाविलगड (अमरावती), महादेव टेकड्या (नागपूर–मध्य प्रदेश सीमा), नागपूरजवळ रामटेक.
## घाट व त्यावरील रस्ते (उत्तरेकडून दक्षिणेकडे)
|घाट|रस्ता|
|थळ (कसारा) घाट|मुंबई–नाशिक (मुंबई–आग्रा महामार्ग)|
|माळशेज घाट|कल्याण–मुरबाड–जुन्नर–अहिल्यानगर|
|नाणेघाट|जुन्नर–कल्याण (सातवाहनकालीन व्यापारी मार्ग; पायवाट)|
|बोर घाट (खंडाळा)|मुंबई–पुणे|
|वरंधा घाट|भोर–महाड|
|आंबेनळी घाट|महाबळेश्वर–पोलादपूर|
|कुंभार्ली घाट|कराड–चिपळूण|
|आंबा घाट|कोल्हापूर–रत्नागिरी|
|फोंडा घाट|कोल्हापूर (राधानगरी)–कणकवली|
|आंबोली घाट|बेळगाव–सावंतवाडी–वेंगुर्ला|
पठारावरील घाट: दिवा घाट (पुणे–सासवड), खंबाटकी घाट (पुणे–सातारा, खंडाळा तालुका), कात्रज घाट (पुणे–सातारा जुना मार्ग). सह्याद्रीचे घाट कोकणाला देशाशी जोडतात; पुणे–रायगड, सातारा–रत्नागिरी, कोल्हापूर–रत्नागिरी, कोल्हापूर–सिंधुदुर्ग हे जिल्हे घाटरस्त्यांनी जोडलेले आहेत.
## कोकण किनारपट्टी
- लांबी सुमारे 720 किमी, रुंदी 30–60 किमी. उत्तरेकडे रुंद, दक्षिणेकडे अरुंद. किनारा खाड्यांनी (creeks) तुटक; अनेक लहान बंदरे.
- उत्तर कोकण (पालघर, ठाणे, मुंबई), मध्य कोकण (रायगड: धरमतर, रेवदंडा, राजपुरी खाड्या), दक्षिण कोकण (रत्नागिरी, सिंधुदुर्ग).
- जलदुर्ग: मुरूड-जंजिरा (रायगड; सिद्दींचा, कधीही जिंकला न गेलेला), सिंधुदुर्ग (मालवण; शिवाजी महाराजांनी 1664 मध्ये बांधला), विजयदुर्ग (देवगड; 'पूर्वेकडील जिब्राल्टर' असेही म्हटले जाते), कुलाबा (अलिबाग), सुवर्णदुर्ग. MPSC उत्तरतालिकेनुसार इंग्रजांनी 'पूर्वेकडील जिब्राल्टर' रायगड किल्ल्याला म्हटले.
## दख्खनचे पठार
- दख्खन पठार बेसॉल्ट खडकाचे (दख्खन ट्रॅप): सुमारे 6.5 कोटी वर्षांपूर्वी भेगी उद्रेकातून (fissure eruption) लाव्हारस पसरून तयार झाले. महाराष्ट्राचा सुमारे 80% भाग व्यापते. अपक्षयातून काळी (रेगूर) मृदा.
- ग्रामीण भागात घरबांधणीसाठी स्थानिक काळा दगड: बेसॉल्ट.
- पठाराचा उतार सर्वसाधारणपणे पूर्व–आग्नेय दिशेकडे, म्हणून मोठ्या नद्या पूर्ववाहिनी. मात्र तापी नदीचे खोरे खचदरी असून तापी पश्चिमेकडे वाहते.
- पठारावरील सपाट माथ्याच्या टेकड्या 'मेसा' व 'बुट्टे' (उदा. पाचगणीचे टेबललँड).
## थंड हवेची ठिकाणे
|ठिकाण|जिल्हा|विशेष|
|महाबळेश्वर|सातारा|सर्वात उंच; स्ट्रॉबेरी; कृष्णेचा उगम|
|पाचगणी|सातारा|टेबललँड|
|माथेरान|रायगड|सर्वात लहान; वाहनबंदी; पर्यावरण संवेदनशील|
|लोणावळा–खंडाळा|पुणे|चिक्की|
|चिखलदरा|अमरावती|विदर्भातील एकमेव; सातपुडा (गाविलगड); कॉफी|
|तोरणमाळ|नंदुरबार|सातपुडा; यशवंत तलाव|
|आंबोली|सिंधुदुर्ग|सर्वाधिक पावसाच्या ठिकाणांपैकी|
|पन्हाळा|कोल्हापूर|ऐतिहासिक किल्ला|
|म्हैसमाळ|छ. संभाजीनगर|मराठवाड्यातील|
|जव्हार|पालघर|आदिवासी भाग|
|भंडारदरा|अहिल्यानगर|आर्थर सरोवर|`;

NOTES.ge5=`## महाराष्ट्रातील नदीखोरी
महाराष्ट्रात पाच प्रमुख नदीप्रणाली आहेत: गोदावरी (सर्वात मोठे खोरे, राज्याच्या सुमारे 49% क्षेत्रावर), कृष्णा (भीमासह), तापी–पूर्णा, नर्मदा (थोडा भाग, नंदुरबार) आणि पश्चिमवाहिनी कोकणी नद्या.
## गोदावरी
- उगम: ब्रह्मगिरी, त्र्यंबकेश्वर (नाशिक). एकूण लांबी सुमारे 1,465 किमी; महाराष्ट्रात सुमारे 668 किमी. महाराष्ट्रातील सर्वात लांब नदी; 'दक्षिण गंगा'. आंध्र प्रदेशात बंगालच्या उपसागराला मिळते.
- काठावरील शहरे: नाशिक, कोपरगाव, पैठण (जायकवाडी धरण, नाथसागर), नांदेड (गुरुद्वारा हजूर साहिब), गंगाखेड.
- उजव्या (दक्षिण) तीरावरील उपनद्या: प्रवरा (मुळा नदी प्रवरेला मिळते; मुळा–प्रवरेचा संयुक्त प्रवाह नेवासे येथील प्रवरासंगमाजवळ गोदावरीला मिळतो), सिंदफणा, मांजरा (बालाघाटात उगम; लातूर, बीड).
- डाव्या (उत्तर) तीरावरील उपनद्या: कादवा, शिवना, खाम, दुधना, पूर्णा (अजिंठ्यात उगम; येलदरी धरण), पैनगंगा–वर्धा–वैनगंगा (प्राणहिता मार्गे), इंद्रावती.
- प्राणहिता: वर्धा (पैनगंगेसह) व वैनगंगा यांचा संयुक्त प्रवाह; सिरोंचाजवळ (गडचिरोली) गोदावरीला मिळते.
- भातसा, वैतरणा या कोकणी (पश्चिमवाहिनी) नद्या गोदावरी खोऱ्याचा भाग नाहीत.
## विदर्भातील नद्या
- वैनगंगा: उगम शिवनी (मध्य प्रदेश); उपनद्या कन्हान (पेंच व कोलार कन्हानला मिळतात), बावनथडी, बाघ, गाढवी; गोसीखुर्द धरण (भंडारा).
- वर्धा: उगम मुलताई (बैतूल, मध्य प्रदेश); उपनद्या वेणा, निरगुडा, इरई, पैनगंगा; अप्पर वर्धा धरण (मोर्शी, अमरावती).
- पैनगंगा: उगम अजिंठा डोंगर (बुलढाणा); इसापूर धरण; वर्धेला मिळते.
## कृष्णा
- उगम: महाबळेश्वर (सातारा). येथे कृष्णा, कोयना, वेण्णा, सावित्री व गायत्री या पाच नद्यांचे उगम मानले जातात (पंचगंगा मंदिर). एकूण लांबी सुमारे 1,400 किमी.
- उपनद्या (महाराष्ट्रात): वेण्णा (संगम माहुली, सातारा), कोयना (कराड येथे 'प्रीतिसंगम'), उरमोडी, येरळा, वारणा (सांगली जवळ), पंचगंगा (कोल्हापूर; नृसिंहवाडी/नरसोबाची वाडी येथे कृष्णा–पंचगंगा संगम), दूधगंगा, वेदगंगा.
- पंचगंगा: कासारी, कुंभी, तुळशी, भोगावती व (गुप्त) सरस्वती या पाच नद्या प्रयाग चिखली (कोल्हापूर) येथे एकत्र येऊन पंचगंगा बनते.
- काठावरील शहरे: वाई, कराड, सांगली, मिरज (जवळ).
## भीमा
- उगम: भीमाशंकर (आंबेगाव, पुणे); कर्नाटकात (रायचूरजवळ) कृष्णेला मिळते. पंढरपूर येथे तिला 'चंद्रभागा' म्हणतात.
- उपनद्या: इंद्रायणी (आळंदी, देहू), मुळा–मुठा (पुणे), भामा, घोड, नीरा (वीर व भाटघर धरणे), सीना, माण. उजनी धरण (यशवंत सागर, सोलापूर).
## तापी–पूर्णा
- तापी: उगम मुलताई (बैतूल, मध्य प्रदेश); लांबी सुमारे 724 किमी; खचदरीतून पश्चिमेकडे वाहते; सुरतजवळ खंबायतच्या आखाताला मिळते. धरणे: हतनूर (जळगाव), उकाई (गुजरात).
- उपनद्या: पूर्णा (सर्वात मोठी; बैतूलजवळ उगम; जळगावमधील चांगदेव/मुक्ताईनगरजवळ तापीला मिळते), गिरणा (नाशिक; गिरणा धरण), पांझरा (धुळे), बोरी, बुराई, अनेर, अरुणावती, गोमाई, वाघूर.
- प्रकाशा (नंदुरबार): तापी–गोमाई–पुलिंदा संगम; 'दक्षिण काशी'.
## नर्मदा
नर्मदा नंदुरबार जिल्ह्याच्या उत्तर सीमेवरून (अक्राणी तालुका) सुमारे 50–60 किमी वाहते आणि महाराष्ट्र–मध्य प्रदेश व महाराष्ट्र–गुजरात सीमा बनवते.
## कोकणातील नद्या (उत्तरेकडून दक्षिणेकडे)
दमणगंगा → वैतरणा → उल्हास → पाताळगंगा → अंबा → कुंडलिका → सावित्री → वाशिष्ठी → शास्त्री → मुचकुंदी → काजळी → कर्ली → तेरेखोल.
- कोकणी नद्या लहान, वेगवान, जलप्रपातयुक्त; मुखाशी खाड्या. सर्वात लांब कोकणी नदी: वैतरणा (उगम त्र्यंबकेश्वरजवळ).
- महाड (रायगड) सावित्री नदीकाठी; चिपळूण वाशिष्ठी नदीकाठी.
## गरम पाण्याचे झरे
वज्रेश्वरी, अकलोली व गणेशपुरी (पूर्वीचा ठाणे जिल्हा, आता पालघर–ठाणे सीमा भाग; MPSC उत्तर 'ठाणे'), उन्हेरे (रायगड), राजापूरची गंगा (रत्नागिरी; ठराविक वर्षांनी प्रकट होणारा झरा), उनकेश्वर (नांदेड), सातिवली (पालघर) (पडताळणी करा).
## धबधबे
रंधा (प्रवरा नदी, भंडारदरा, अहिल्यानगर), ठोसेघर (सातारा), सौताडा (बीड), मार्लेश्वर (रत्नागिरी), आंबोली (सिंधुदुर्ग), दुधसागर (गोवा–कर्नाटक सीमा).`;

